module Zocalo.Gallery.WebReqSpec(tests) where

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit((@?=))

import Zocalo.Gallery.Auth.WebReq(transform)


tests :: Test
tests =
  testGroup "Zocalo.Gallery.Auth.WebReq.transform (HTML -> plain-text e-mail part)"
    [ testCase "leaves plain text alone" $
        transform "just text" @?= "just text"

    , testCase "turns <br> into newlines and drops other tags" $
        transform "Your code is:<br><b>012345</b><br>Bye" @?= "Your code is:\n012345\nBye"

    , testCase "keeps the text of a link (note: the href itself is dropped)" $
        transform "Click <a href='https://x.example/y'>here</a>." @?= "Click here."
    ]
